spec.section:
# metric-checkpoint.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/metric-checkpoint.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "description": "Immutable collector checkpoint written before counted records may be compacted or tombstoned.",
  "properties": {
    "buckets": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "dedupe_digest": {
            "minLength": 1,
            "type": "string"
          },
          "end": {
            "format": "date-time",
            "type": "string"
          },
          "event_count": {
            "minimum": 0,
            "type": "integer"
          },
          "start": {
            "format": "date-time",
            "type": "string"
          },
          "value": {
            "minimum": 0,
            "type": "number"
          }
        },
        "required": [
          "start",
          "end",
          "value",
          "event_count",
          "dedupe_digest"
        ],
        "type": "object"
      },
      "type": "array"
    },
    "checkpoint_id": {
      "pattern": "^mcp-[A-Za-z0-9._:-]+$",
      "type": "string"
    },
    "created_at": {
      "format": "date-time",
      "type": "string"
    },
    "dedupe_epoch": {
      "minLength": 1,
      "type": "string"
    },
    "labels": {
      "additionalProperties": false,
      "properties": {
        "label_schema_version": {
          "minimum": 1,
          "type": "integer"
        },
        "values": {
          "additionalProperties": {
            "type": "string"
          },
          "type": "object"
        }
      },
      "required": [
        "label_schema_version",
        "values"
      ],
      "type": "object"
    },
    "metric": {
      "pattern": "^[a-z][a-z0-9_]*(?:_total|_seconds|_tokens|_inflight)$",
      "type": "string"
    },
    "migration": {
      "additionalProperties": false,
      "properties": {
        "from_schema_version": {
          "minimum": 1,
          "type": "integer"
        },
        "loss": {
          "enum": [
            "none",
            "explicit_gap"
          ],
          "type": "string"
        },
        "transform": {
          "minLength": 1,
          "type": "string"
        }
      },
      "type": "object"
    },
    "reconstruction": {
      "additionalProperties": false,
      "properties": {
        "algorithm": {
          "enum": [
            "checkpoint_plus_events",
            "canonical_attempt_run_state"
          ],
          "type": "string"
        },
        "canonical_state": {
          "minLength": 1,
          "type": "string"
        },
        "restart_safe": {
          "const": true,
          "type": "boolean"
        },
        "tombstone_safe": {
          "const": true,
          "type": "boolean"
        }
      },
      "required": [
        "algorithm",
        "canonical_state",
        "tombstone_safe",
        "restart_safe"
      ],
      "type": "object"
    },
    "retention": {
      "additionalProperties": false,
      "properties": {
        "checkpoint_days": {
          "minimum": 1,
          "type": "integer"
        },
        "source_event_days": {
          "minimum": 0,
          "type": "integer"
        },
        "tombstone_requires_checkpoint": {
          "const": true,
          "type": "boolean"
        }
      },
      "required": [
        "checkpoint_days",
        "source_event_days",
        "tombstone_requires_checkpoint"
      ],
      "type": "object"
    },
    "schema_version": {
      "minimum": 1,
      "type": "integer"
    },
    "scope": {
      "enum": [
        "since_start",
        "rolling_24h",
        "instant"
      ],
      "type": "string"
    },
    "since_start_total": {
      "minimum": 0,
      "type": "number"
    },
    "source_kind": {
      "enum": [
        "durable_metric_event",
        "attempt_run_state",
        "wait_record",
        "report_record",
        "archive_record",
        "bridge_record",
        "measurement_sample"
      ],
      "type": "string"
    },
    "source_watermark": {
      "additionalProperties": false,
      "properties": {
        "commit_seq": {
          "minimum": 0,
          "type": "integer"
        },
        "event_id": {
          "minLength": 1,
          "type": "string"
        },
        "namespace": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "namespace",
        "commit_seq",
        "event_id"
      ],
      "type": "object"
    }
  },
  "required": [
    "schema_version",
    "checkpoint_id",
    "metric",
    "labels",
    "source_kind",
    "scope",
    "source_watermark",
    "dedupe_epoch",
    "since_start_total",
    "buckets",
    "reconstruction",
    "created_at"
  ],
  "title": "CHD retention-safe metric checkpoint",
  "type": "object"
}
```
